#!/usr/bin/env python3

# Filename:    pull_request_body.py
# Author:      Homelab-Alpha
# Date:        2026-10-29
# Version:     1.0.0

# Description: Builds the description of a pull request that a workflow opens,
#              from .github/pull_request_template.md. Every heading and every
#              HTML comment of the template stays. The sections are filled in,
#              only the boxes that are true are ticked, and the optional
#              screenshots section is removed. A pull request of a workflow
#              then looks like the pull request of a person.
#
#              The script stops with an error when the template no longer has
#              a heading or a placeholder it fills, so a change of the template
#              is noticed and does not give a pull request with a broken body.
#
#              Uses the Python standard library only.
#
# Usage:
#   python3 .github/scripts/pull_request_body.py \
#     --repo owner/name \
#     --type docs \
#     --description "Updates CONTRIBUTORS.md." \
#     --steps "1. Open the Files changed tab." \
#     --notes "Automatically generated by the Update Contributors workflow." \
#     > pull_request_body.md
#
# Options:
#   --repo         Repository (owner/name). Fills {{GITHUB_USERNAME}} and
#                  {{PROJECT_NAME}} when the template still has them.
#   --type         Type of change to tick: fix, feat, feat!, docs, style,
#                  refactor, perf, test, chore, revert, build, or ci.
#   --description  Text of the Description section.
#   --related      Text of the Related Issues section (default: None.).
#   --environment  Text of the Test Environment section
#                  (default: GitHub Actions on ubuntu-26.04.).
#   --steps        Text of the Steps to Test section.
#   --notes        Text of the Additional Notes section.
#   --check        Part of the text of one more checklist item to tick. It can
#                  be used more than once and must match exactly one item.
#   --template     Path of the template (default:
#                  .github/pull_request_template.md). Without that file the
#                  template is read from the default branch through the API.

import argparse
import base64
import logging
import re
import subprocess
import sys

logging.basicConfig(level=logging.INFO, format="pull_request_body.py: %(message)s")

TEMPLATE = ".github/pull_request_template.md"

# The boxes a workflow can tick without doing anything: the pull request has a
# conventional title, a branch and commits that follow the convention, no
# conflicts, and no secrets, and it starts from the current base branch.
DEFAULT_CHECKS = (
    "The title of this pull request is a conventional commit",
    "My branch name follows",
    "My commits follow",
    "My branch is up to date",
    "There are no merge conflicts",
    "This pull request does not introduce any secrets",
)

# The heading above each placeholder ("...") in the template, and the option
# that fills it.
SECTIONS = (
    ("## 📋 Description", "description"),
    ("### Related Issues", "related"),
    ("### Test Environment", "environment"),
    ("### Steps to Test", "steps"),
    ("## 📝 Additional Notes", "notes"),
)

SCREENSHOTS = re.compile(r"## 📸 Screenshots or Logs\n.*?\n---\n\n(?=## )", re.S)


def fail(message):
    logging.error(message)
    sys.exit(1)


def read_template(path, repo):
    try:
        with open(path, encoding="utf-8") as handle:
            return handle.read()
    except FileNotFoundError:
        pass
    result = subprocess.run(
        ["gh", "api", f"repos/{repo}/contents/{TEMPLATE}", "--jq", ".content"],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0 or not result.stdout.strip():
        fail(f"the template {path} was not found and could not be read from {repo}: {result.stderr.strip()}")
    return base64.b64decode(result.stdout).decode("utf-8")


def fill(text, heading, value):
    """Replace the first placeholder line ("...") after the heading with the value."""
    start = text.find(f"\n{heading}\n")
    if start == -1:
        fail(f"the template has no heading '{heading}'")
    match = re.compile(r"^\.\.\.$", re.M).search(text, start)
    if match is None:
        fail(f"the template has no placeholder below '{heading}'")
    return text[: match.start()] + value.strip("\n") + text[match.end() :]


def tick(text, needle):
    """Tick the one unchecked box whose line contains the needle."""
    lines = text.split("\n")
    found = [i for i, line in enumerate(lines) if line.startswith("- [ ] ") and needle in line]
    if len(found) != 1:
        fail(f"'{needle}' matches {len(found)} unchecked boxes, not one")
    lines[found[0]] = lines[found[0]].replace("- [ ] ", "- [x] ", 1)
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description="Build a pull request body from the template.")
    parser.add_argument("--repo", required=True)
    parser.add_argument("--type", required=True, dest="kind")
    parser.add_argument("--description", required=True)
    parser.add_argument("--related", default="None.")
    parser.add_argument("--environment", default="GitHub Actions on `ubuntu-26.04`.")
    parser.add_argument("--steps", required=True)
    parser.add_argument("--notes", required=True)
    parser.add_argument("--check", action="append", default=[])
    parser.add_argument("--template", default=TEMPLATE)
    args = parser.parse_args()

    owner, _, name = args.repo.partition("/")
    text = read_template(args.template, args.repo)
    text = text.replace("{{GITHUB_USERNAME}}", owner).replace("{{PROJECT_NAME}}", name)

    for heading, option in SECTIONS:
        text = fill(text, heading, getattr(args, option))

    # The screenshots section is optional and a workflow has nothing to show.
    text = SCREENSHOTS.sub("", text)

    text = tick(text, f"`{args.kind}`")
    for needle in (*DEFAULT_CHECKS, *args.check):
        text = tick(text, needle)

    sys.stdout.write(text if text.endswith("\n") else text + "\n")


if __name__ == "__main__":
    main()
